/* apiref_sidebar.js -- render the API reference left rail from window.APIREF_NAV.
 *
 * Design goals (the old globaltoc rail failed all three):
 *   workable  - scoped tree, only the current page's ancestors auto-expand,
 *               a filter box, active item scrolled into view, state remembered.
 *   flexible  - the whole tree is data (apiref_nav.js, generated by
 *               `apiref.py wire`); adding a page never touches this file.
 *   not brittle- one DOM hook (.sphinxsidebarwrapper), our own markup and
 *               classes, no dependence on alabaster's toctree HTML, capped
 *               indentation, wrapping labels.
 */
(function () {
  "use strict";

  // The bundle may carry several framework nav trees (lymph, classic, ...).
  // Pick the one whose pages match the current URL; fall back to the primary.
  var DATA = window.APIREF_NAV;
  var ALL = window.APIREF_NAV_ALL;
  if (Array.isArray(ALL) && ALL.length > 1) {
    var here = currentRelPath();
    var hit = ALL.filter(function (b) {
      if (!b || !b.framework) return false;
      if (b.prefix) return here.indexOf(b.prefix) === 0;
      return here.indexOf("api/" + b.framework + "/") === 0 ||
             here.indexOf("api/plussai_" + b.framework) === 0;
    })[0];
    DATA = hit || null;
  }
  if (!DATA || !Array.isArray(DATA.tree)) return;

  var STORE_KEY = "apiref-nav:open";
  var MAX_TIER = 2; // indentation stops growing past this depth

  function ready(fn) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else {
      fn();
    }
  }

  // Path of the current page relative to the docs root, e.g. "api/lymph/models/Model/learn.html".
  function currentRelPath() {
    var root = "";
    if (window.DOCUMENTATION_OPTIONS && typeof window.DOCUMENTATION_OPTIONS.URL_ROOT === "string") {
      root = window.DOCUMENTATION_OPTIONS.URL_ROOT;
    } else {
      var attr = document.documentElement.getAttribute("data-content_root");
      if (attr) root = attr;
    }
    try {
      var base = new URL(root, window.location.href);
      var rel = decodeURIComponent(window.location.pathname).slice(
        decodeURIComponent(base.pathname).length
      );
      return rel.replace(/^\/+/, "");
    } catch (e) {
      return (window.location.pathname.split("/").pop() || "");
    }
  }

  function hrefFor(page) {
    var root = "";
    if (window.DOCUMENTATION_OPTIONS && typeof window.DOCUMENTATION_OPTIONS.URL_ROOT === "string") {
      root = window.DOCUMENTATION_OPTIONS.URL_ROOT;
    } else {
      root = document.documentElement.getAttribute("data-content_root") || "";
    }
    return root + page;
  }

  // Expanded branches are remembered so that opening one family never collapses
  // another. localStorage carries the set across page loads; a cookie is the
  // fallback for contexts where localStorage is blocked (sandboxed viewers,
  // some file:// setups) so multi-expand still survives navigation there.
  function readStore() {
    try {
      var raw = window.localStorage.getItem(STORE_KEY);
      if (raw != null) return raw;
    } catch (e) { /* fall through to cookie */ }
    var m = document.cookie.match(/(?:^|;\s*)apiref_nav_open=([^;]*)/);
    return m ? decodeURIComponent(m[1]) : null;
  }

  function writeStore(value) {
    var wrote = false;
    try { window.localStorage.setItem(STORE_KEY, value); wrote = true; } catch (e) { /* ignore */ }
    try {
      document.cookie = "apiref_nav_open=" + encodeURIComponent(value) +
        ";path=/;max-age=31536000;samesite=lax";
      wrote = true;
    } catch (e) { /* ignore */ }
    return wrote;
  }

  function loadOpen() {
    try {
      var raw = readStore();
      return raw ? new Set(JSON.parse(raw)) : new Set();
    } catch (e) {
      return new Set();
    }
  }

  function saveOpen(set) {
    writeStore(JSON.stringify(Array.from(set)));
  }

  // Ancestor chain (list of node.page) whose subtree contains `target`.
  function ancestorPages(nodes, target, trail, out) {
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i];
      var here = trail.concat(n.page ? [n.page] : []);
      if (n.page === target) {
        for (var k = 0; k < trail.length; k++) out.add(trail[k]);
        return true;
      }
      if (n.children && ancestorPages(n.children, target, here, out)) {
        if (n.page) out.add(n.page);
        return true;
      }
    }
    return false;
  }

  function el(tag, cls, attrs) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (attrs) Object.keys(attrs).forEach(function (k) { e.setAttribute(k, attrs[k]); });
    return e;
  }

  function build() {
    var wrapper = document.querySelector(".sphinxsidebarwrapper")
      || document.querySelector("div.sphinxsidebar");
    if (!wrapper) return;

    // Only take over on API reference pages.
    var cur = currentRelPath();
    if (cur.indexOf("api/") === -1 && cur.indexOf("manual/") !== 0) return;

    var openSet = loadOpen();
    var forced = new Set();
    ancestorPages(DATA.tree, cur, [], forced);
    forced.forEach(function (p) { openSet.add(p); });

    var nav = el("nav", "apiref-nav");
    nav.setAttribute("aria-label", DATA.title || "API navigation");

    // --- header -----------------------------------------------------------
    var head = el("div", "apiref-nav__head");
    var title = el("a", "apiref-nav__title");
    title.href = hrefFor(DATA.root_page || "api_reference.html");
    title.textContent = DATA.title || "API Reference";
    head.appendChild(title);

    var filter = el("input", "apiref-nav__filter", {
      type: "search",
      placeholder: "Filter…",
      "aria-label": "Filter navigation",
      autocomplete: "off",
      spellcheck: "false",
    });
    head.appendChild(filter);
    nav.appendChild(head);

    // --- scroll region + tree ------------------------------------------------
    var scroll = el("div", "apiref-nav__scroll");
    var tree = el("ul", "apiref-nav__tree");
    scroll.appendChild(tree);
    nav.appendChild(scroll);

    var activeLink = null;

    function renderNode(node, depth) {
      var li = el("li", "apiref-nav__item", { "data-type": node.type || "page" });
      var kids = Array.isArray(node.children) ? node.children : [];
      var tier = Math.min(depth, MAX_TIER);

      var row = el("div", "apiref-nav__row" + (kids.length ? "" : " is-leaf"));

      if (kids.length) {
        var toggle = el("button", "apiref-nav__toggle", {
          type: "button",
          "aria-label": "Toggle " + (node.label || "section"),
        });
        toggle.addEventListener("click", function () {
          var open = li.classList.toggle("is-open");
          toggle.setAttribute("aria-expanded", open ? "true" : "false");
          if (node.page) {
            if (open) openSet.add(node.page); else openSet.delete(node.page);
            saveOpen(openSet);
          }
        });
        row.appendChild(toggle);
      }

      var link = el("a", "apiref-nav__link");
      link.textContent = node.label || "(untitled)";
      link.href = node.page ? hrefFor(node.page) : "#";
      if (node.page) link.dataset.page = node.page;
      link.style.setProperty("--tier", String(tier));
      if (node.page && node.page === cur) {
        link.classList.add("is-active");
        link.setAttribute("aria-current", "page");
        activeLink = link;
      }
      row.appendChild(link);
      li.appendChild(row);

      if (kids.length) {
        var ul = el("ul", "apiref-nav__children");
        kids.forEach(function (c) { ul.appendChild(renderNode(c, depth + 1)); });
        li.appendChild(ul);
        if (node.page && openSet.has(node.page)) li.classList.add("is-open");
        if (node.page && forced.has(node.page)) li.classList.add("is-open", "has-active");
        // landing on an object's own page: reveal its members straight away
        if (node.page && node.page === cur) li.classList.add("is-open");
        var t = row.querySelector(".apiref-nav__toggle");
        if (t) t.setAttribute("aria-expanded", li.classList.contains("is-open") ? "true" : "false");
      }
      return li;
    }

    DATA.tree.forEach(function (n) { tree.appendChild(renderNode(n, 0)); });

    if (!tree.children.length) {
      var empty = el("div", "apiref-nav__empty");
      empty.textContent = "Navigation data is empty. Run `apiref.py wire`.";
      scroll.appendChild(empty);
    }

    // --- filter behaviour -------------------------------------------------
    var allItems = Array.prototype.slice.call(tree.querySelectorAll(".apiref-nav__item"));
    function pageOf(li) {
      var link = li.querySelector(":scope > .apiref-nav__row > .apiref-nav__link");
      return link ? link.dataset.page : null;
    }
    function applyFilter(q) {
      q = (q || "").trim().toLowerCase();
      if (!q) {
        // clear: everything visible again; open state returns to what the
        // reader actually expanded (stored) plus the current page's ancestors.
        allItems.forEach(function (li) {
          li.hidden = false;
          var p = pageOf(li);
          var shouldOpen = p && (openSet.has(p) || forced.has(p) || p === cur);
          li.classList.toggle("is-open", !!shouldOpen);
        });
        return;
      }
      // bottom-up: an item is visible if it matches or any descendant matches
      for (var i = allItems.length - 1; i >= 0; i--) {
        var li = allItems[i];
        var label = li.querySelector(":scope > .apiref-nav__row > .apiref-nav__link");
        var selfMatch = label && label.textContent.toLowerCase().indexOf(q) !== -1;
        var childMatch = !!li.querySelector(".apiref-nav__item:not([hidden])");
        var visible = selfMatch || childMatch;
        li.hidden = !visible;
        if (visible && childMatch) li.classList.add("is-open");
      }
    }
    var debounce;
    filter.addEventListener("input", function () {
      window.clearTimeout(debounce);
      var v = filter.value;
      debounce = window.setTimeout(function () { applyFilter(v); }, 90);
    });
    filter.addEventListener("keydown", function (e) {
      if (e.key === "Escape") { filter.value = ""; applyFilter(""); }
    });

    // --- narrow-screen disclosure ------------------------------------------
    // On small screens the rail sits above the content; start it collapsed
    // and let the header act as a show/hide toggle.
    var isNarrow = window.innerWidth <= 1024;
    if (isNarrow) nav.classList.add("is-collapsed");
    head.addEventListener("click", function (e) {
      if (e.target === filter) return;
      if (window.innerWidth <= 1024) nav.classList.toggle("is-collapsed");
    });

    // --- mount ---------------------------------------------------------
    document.body.classList.add("apiref-page");
    wrapper.innerHTML = "";
    wrapper.appendChild(nav);

    if (activeLink) {
      requestAnimationFrame(function () {
        try {
          activeLink.scrollIntoView({ block: "center", inline: "nearest" });
        } catch (e) {
          activeLink.scrollIntoView();
        }
      });
    }
  }

  ready(build);
})();
